type Gate =
  | { kind: 'ok' }
  | { kind: 'update-available' }      // prompt, dismissible
  | { kind: 'update-required'; reason: string };  // block, not dismissible

/**
 * Checked on launch and on return to foreground. The response is cached with
 * a short TTL so a dead config endpoint cannot lock anyone out of the app -
 * failing open is correct here, because the alternative is bricking every
 * install the moment a server has a bad morning.
 */
export async function checkGate(build: number): Promise<Gate> {
  const config = await remoteConfig.fetch({ ttlSeconds: 300 }).catch(() => null);
  if (!config) return { kind: 'ok' };

  // minimumBuild is raised only to recall a broken release. It is the one
  // lever that works on an app already installed on someone's phone.
  if (build < config.minimumBuild) {
    return { kind: 'update-required', reason: config.recallReason };
  }
  if (build < config.latestBuild) return { kind: 'update-available' };
  return { kind: 'ok' };
}

/**
 * Shipping dark: the code is in the build that passed review, switched on
 * later without a second submission. Default false, so a flag the server
 * has never heard of stays off rather than enabling itself.
 */
export function isEnabled(flag: FlagName, userId: string): boolean {
  const rule = remoteConfig.flags[flag];
  if (!rule?.enabled) return false;
  if (rule.percentage >= 100) return true;

  // Stable per user: a feature must not flicker on and off between launches.
  return hashToPercent(`${flag}:${userId}`) < rule.percentage;
}
